INSERT OR IGNORE INTO questions (id, exam_id, order_num, question_text, question_image, question_type, points) VALUES ('4ecb7fff-edb1-4c74-a1e9-fd4a7d1deb68', '98fd1113-8e0b-4643-8d26-f452b1e934ac', 23, 'ข้อใดกล่าวไม่ถูกต้องเกี่ยวกับการประเมินความน่าเชื่อถือของข้อมูลโดยใช้ PROMRT', NULL, 'multiple_choice', 1);
INSERT OR IGNORE INTO choices (id, question_id, order_num, choice_text, choice_image, is_correct) VALUES ('4d2e27ed-d16b-4e02-98c5-05451ffb487f', '4ecb7fff-edb1-4c74-a1e9-fd4a7d1deb68', 1, 'การประเมินข้อมูลแบบ PROMRTต้องประเมินเนื้อหาในอดีต ซึ่งต้องทำอย่างละเอียดรอบคอบ', NULL, 1);
INSERT OR IGNORE INTO choices (id, question_id, order_num, choice_text, choice_image, is_correct) VALUES ('2d9756ef-3f4b-4acc-bc2a-d9fcd60bb6a0', '4ecb7fff-edb1-4c74-a1e9-fd4a7d1deb68', 2, 'การประเมินข้อมูลแบบ PROMRT ต้องมีการตั้งคำถามก่อนที่จะนำข้อมูลเหล่านั้นมาประเมินผล', NULL, 0);
INSERT OR IGNORE INTO choices (id, question_id, order_num, choice_text, choice_image, is_correct) VALUES ('13e63cac-bc6b-42a1-8e05-fad90c4714a3', '4ecb7fff-edb1-4c74-a1e9-fd4a7d1deb68', 3, 'การประเมินข้อมูลแบบ PROMRTต้องมีการพิสูจน์ หรือมีการอ้างอิงข้อมูลเนื้อหาจากแหล่งอ้างอิง', NULL, 0);
INSERT OR IGNORE INTO choices (id, question_id, order_num, choice_text, choice_image, is_correct) VALUES ('54e4e8dd-c63a-4e22-8413-008d45a38cdf', '4ecb7fff-edb1-4c74-a1e9-fd4a7d1deb68', 4, 'การประเมินข้อมูลแบบ PROMRTต้องตระหนักถึงความคิดเห็นและวาระที่ต้องการเป็นสิ่งสำคัญ', NULL, 0);
INSERT OR IGNORE INTO questions (id, exam_id, order_num, question_text, question_image, question_type, points) VALUES ('3371d77f-8afb-4a17-941d-72dc150588be', '98fd1113-8e0b-4643-8d26-f452b1e934ac', 24, 'ข้อใด คือ เหตุผลเชิงวิบัติโดยอ้างอำนาจ', NULL, 'multiple_choice', 1);
INSERT OR IGNORE INTO choices (id, question_id, order_num, choice_text, choice_image, is_correct) VALUES ('a7a83a3b-2f64-4274-8104-5ce7f7170869', '3371d77f-8afb-4a17-941d-72dc150588be', 1, 'คุณควรได้อ่านการ์ตูนเรื่องพลิกดินสู่ดาวทุกตอนนะ หนังสือการ์ตูนเรื่องนี้ขายได้กว่าล้านเล่มแล้วทั่วโลก และตอนนี้ใคร ๆ ก็กำลังพูดถึงหนังสือเรื่องนี้กัน', NULL, 0);
INSERT OR IGNORE INTO choices (id, question_id, order_num, choice_text, choice_image, is_correct) VALUES ('af65727d-7bbe-4f26-a423-d1b80e273884', '3371d77f-8afb-4a17-941d-72dc150588be', 2, 'ตำแหน่งหัวหน้าที่ว่างในแผนกการจัดการนี้ควรให้แก่อรรถพันธ์นะ เพราะครอบครัวของเขากำลังลำบาก ภรรยาก็ถูกไล่ออกจากงาน ลูกก็ยังเล็ก คุณพ่อของเขาก็กำลังป่วย', NULL, 0);
INSERT OR IGNORE INTO choices (id, question_id, order_num, choice_text, choice_image, is_correct) VALUES ('24e49f87-a741-462d-97ca-db52c7579923', '3371d77f-8afb-4a17-941d-72dc150588be', 3, 'คุณต้องอยากได้และอยากซื้อกระเป๋ากระต่ายแน่ ๆ เพราะแบรนด์กระต่าย เป็นกระเป๋าที่มีคุณภาพ คนมีฐานะและมีชื่อเสียงในสังคมใช้กระเป๋ายี่ห้อนี้กันทั้งนั้นแหละค่ะ', NULL, 0);
INSERT OR IGNORE INTO choices (id, question_id, order_num, choice_text, choice_image, is_correct) VALUES ('69421eba-594f-4583-a9ee-40359f97bcfc', '3371d77f-8afb-4a17-941d-72dc150588be', 4, 'ผมรู้ว่าพวกคุณไม่เห็นด้วยกับการที่สุธีขึ้นเป็นหัวหน้าของพวกคุณ แต่อย่างไรก็ตามถ้าสุธีไม่ได้ตำแหน่งนี้พวกเราอาจจะต้องหางานใหม่', NULL, 1);
INSERT OR IGNORE INTO questions (id, exam_id, order_num, question_text, question_image, question_type, points) VALUES ('512d1ecd-6088-497b-a649-ccbd1d0221bd', '98fd1113-8e0b-4643-8d26-f452b1e934ac', 25, 'พิจารณาข้อมูลที่กำหนดให้แล้วตอบคำถามข้อ 18 นักวิทยาศาสตร์ที่ทำการศึกษาระบบนิเวศในเขตอาร์กติกพบว่า หมีพิซลี (Pizzly) ซึ่งเป็นลูกผสมของหมีขั้ว โลกหรือโพลาร์แบร์ (Polar bear) กับหมีสีน้ำตาลหรือหมีกริซลี (Grizzly) กำลังเพิ่มจำนวนขึ้นอย่างรวดเร็ว และมุ่งเข้าหากินในดินแดนทางตอนเหนือมากขึ้นเรื่อย ๆ สวนทางกับหมีขั้วโลกที่มีประชากรลดน้อยลงเรื่อย ๆ จากผลกระทบของ Climate change จนเกิดการขาดแคลนอาหารและอยู่ในภาวะเสี่ยงสูญพันธุ์" แหล่งที่มา: เว็บไซต์สำนักข่าว BBC News "ข้อมูลข่าวข้างต้นเป็นข้อมูลที่นักเรียนสามารถนำไปใช้อ้างอิงในการทำรายงานเรื่อง Climate change ได้หรือไม่ อย่างไร', NULL, 'multiple_choice', 1);
INSERT OR IGNORE INTO choices (id, question_id, order_num, choice_text, choice_image, is_correct) VALUES ('90dae632-b5b7-416d-9498-cbe3923dc15c', '512d1ecd-6088-497b-a649-ccbd1d0221bd', 1, 'ใช้อ้างอิงได้ เพราะ เป็นข้อมูลที่น่าสนใจ', NULL, 0);
INSERT OR IGNORE INTO choices (id, question_id, order_num, choice_text, choice_image, is_correct) VALUES ('07c4772b-09d6-487d-9f3d-f685a107291c', '512d1ecd-6088-497b-a649-ccbd1d0221bd', 2, 'ไม่ควรใช้อ้างอิง เพราะ เนื้อหามีรายละเอียดน้อยไป', NULL, 0);
INSERT OR IGNORE INTO choices (id, question_id, order_num, choice_text, choice_image, is_correct) VALUES ('6fffe666-ebd0-4dc6-a7bc-547d8e705808', '512d1ecd-6088-497b-a649-ccbd1d0221bd', 3, 'ใช้อ้างอิงได้ เพราะ เป็นข้อมูลจากแหล่งที่มีความน่าเชื่อถือ', NULL, 1);
INSERT OR IGNORE INTO choices (id, question_id, order_num, choice_text, choice_image, is_correct) VALUES ('0126cfbe-c72b-4432-bd92-21c2093e6514', '512d1ecd-6088-497b-a649-ccbd1d0221bd', 4, 'ไม่ควรใช้อ้างอิง เพราะ เนื้อหาไม่เกี่ยวข้องกับหัวข้อรายงานโดยตรง', NULL, 0);
INSERT OR IGNORE INTO questions (id, exam_id, order_num, question_text, question_image, question_type, points) VALUES ('eb3f79ef-847f-4878-b636-7cf9e3d5e39c', '98fd1113-8e0b-4643-8d26-f452b1e934ac', 26, 'บอลต้องการหาข้อมูลเกี่ยวกับการใช้โทรศัพท์มือถือของคนในปัจจุบัน จึงไปพบบทความแสดงข้อมูลที่เกี่ยวข้อง ดังนี้ เปิดเผยการสำรวจเทคโนโลยีสารสนเทศและการสื่อสารของครัวเรือนไทยว่าในช่วงปีพ.ศ.2546-2549 พบว่า การใช้โทรศัพท์มือถือของคนไทยมีแนวโน้มเพิ่มขึ้นอย่างต่อเนื่องในช่วง 3 ปีที่ผ่านมา ระหว่างปีพ.ศ. 2546-2549 โดยในปีพ.ศ. 2549 จำนวนคนไทยใช้โทรศัพท์มือถือเพิ่มขึ้นจากปีพ.ศ. 2546 เกือบเท่าตัว คือ ในปีพ.ศ. 2546 จากประชากร 100 คน มีโทรศัพท์มือถือใช้ 23 คน และในปีพ.ศ. 2549 จำนวนคนไทยใช้โทรศัพท์มือถือเพิ่มขึ้นเป็น 42 เมื่อนำข้อมูลที่กำหนดให้มาประเมินความน่าเชื่อถือของข้อมูลโดยใช้ PROMPT ข้อใดกล่าวถูกต้อง', NULL, 'multiple_choice', 1);
INSERT OR IGNORE INTO choices (id, question_id, order_num, choice_text, choice_image, is_correct) VALUES ('e165f92a-d94d-4c5b-9665-72c0e99024bc', 'eb3f79ef-847f-4878-b636-7cf9e3d5e39c', 1, 'การนำเสนอข้อมูลที่ได้ไม่มีความชัดเจนเป็นเพียงการกล่าวถึงการใช้โทรศัพท์มือถือของคนไทย', NULL, 0);
