INSERT OR IGNORE INTO choices (id, question_id, order_num, choice_text, choice_image, is_correct) VALUES ('9f6fa02d-2d41-4f7d-b532-deb2d3b09a5e', 'eb3f79ef-847f-4878-b636-7cf9e3d5e39c', 3, 'การนำเสนอข้อมูลมีวัตถุประสงค์ชัดเจน มีความน่าเชื่อถือ', NULL, 0);
INSERT OR IGNORE INTO choices (id, question_id, order_num, choice_text, choice_image, is_correct) VALUES ('81412f63-8be0-4607-9438-7fc32d734eb6', 'eb3f79ef-847f-4878-b636-7cf9e3d5e39c', 4, 'ข้อมูลนี้จัดทำเมื่อปี 2549 ซึ่งเป็นข้อมูลเก่าไม่ทันต่อเหตุการณ์ในปัจจุบัน', NULL, 1);
