INSERT OR IGNORE INTO questions (id, exam_id, order_num, question_text, question_image, question_type, points) VALUES ('3995986a-6e54-4c4b-8143-d4b085f4edb1', '98fd1113-8e0b-4643-8d26-f452b1e934ac', 28, 'อ่านข้อมูลต่อไปนี้ แล้วตอบคำถามข้อ 19. - 20. ระหว่างที่มีการแพร่ระบาดของเชื้อไวรัสโควิด-19 มีผู้ปล่อยข่าวลวงทางโซเชียลต่อเนื่องกัน ดังนี้ หลังได้รับข่าวลวง นักเรียน 4 คนมีพฤติกรรมดังนี้ จากสถานการณ์ข้างต้น ใครมีทักษะรู้เท่าทันสื่อมากที่สุด', NULL, 'multiple_choice', 1);
