INSERT OR IGNORE INTO questions (id, exam_id, order_num, question_text, question_image, question_type, points) VALUES ('0b76168d-45c4-45f0-82f0-14100ab9cd7d', '98fd1113-8e0b-4643-8d26-f452b1e934ac', 29, 'ตำรวจกำลังแจ้งข้อหากับเด็กหญิงคนหนึ่ง ที่เข้าไปขโมยยารักษาโรคที่ร้านขายยาแห่งหนึ่ง มีผู้ชายที่เป็น ลูกค้ามาบอกกับตำรวจว่า “เธอมีความจำเป็นที่ต้องขโมย เพราะ ต้องการนำยาไปรักษาอาการของแม่ ที่ป่วยอยู่ แล้วบ้านของเธอก็ยากจนอีกด้วย” จากสถานการณ์ข้างต้น เป็นการให้เหตุผลเชิงวิบัติแบบใด', NULL, 'multiple_choice', 1);
INSERT OR IGNORE INTO choices (id, question_id, order_num, choice_text, choice_image, is_correct) VALUES ('17055cd1-6055-4b33-bec5-d87e6ce62c35', '0b76168d-45c4-45f0-82f0-14100ab9cd7d', 1, 'เป็นการให้เหตุผลโดยอ้างความน่าสงสาร แล้วเปลี่ยนให้เป็นความถูกต้อง', NULL, 1);
INSERT OR IGNORE INTO choices (id, question_id, order_num, choice_text, choice_image, is_correct) VALUES ('4b79e8e7-45a4-4a39-89df-d2d57c7122ff', '0b76168d-45c4-45f0-82f0-14100ab9cd7d', 2, 'เป็นการให้เหตุผลโดยสร้างทางเลือกไว้แค่ 2 ทาง แต่ในความเป็นจริงอาจจะมีทางเลือกอื่นอีก', NULL, 0);
INSERT OR IGNORE INTO choices (id, question_id, order_num, choice_text, choice_image, is_correct) VALUES ('97d6d340-0d46-49e9-a555-2d8e7f04c422', '0b76168d-45c4-45f0-82f0-14100ab9cd7d', 3, 'เป็นการให้เหตุผลเกินจริง โดยการบอกเหตุผลว่าเมื่อเกิดสิ่งนี้แล้วจะทำให้เกิดอีกสิ่งหนึ่งตามมาซึ่งเกิน ความจริงไปมาก', NULL, 0);
INSERT OR IGNORE INTO choices (id, question_id, order_num, choice_text, choice_image, is_correct) VALUES ('355efddb-112c-45fc-bffd-ff6e766713f6', '0b76168d-45c4-45f0-82f0-14100ab9cd7d', 4, 'เป็นการให้เหตุผลเบี่ยงเบนประเด็น จากการโต้แย้งกับผู้อื่นให้กลายเป็นอีกเรื่องแล้วโจมตีจากประเด็น ที่ถูกบิดเบือน', NULL, 0);
INSERT OR IGNORE INTO questions (id, exam_id, order_num, question_text, question_image, question_type, points) VALUES ('6a25ff62-a05e-4971-93a6-27da06929903', '98fd1113-8e0b-4643-8d26-f452b1e934ac', 30, 'บุคคลใดนำความรู้เกี่ยวกับการรู้เท่าทันสื่อดิจิทัลไปใช้ประโยชน์', NULL, 'multiple_choice', 1);
INSERT OR IGNORE INTO choices (id, question_id, order_num, choice_text, choice_image, is_correct) VALUES ('0d22e51a-ac43-4856-b898-68d9786bcc95', '6a25ff62-a05e-4971-93a6-27da06929903', 1, 'แอนแชร์วิธีการทำขนมเค้กที่ได้จากเพจชื่อดังลงในเฟซบุ๊กส่วนตัวเพื่อให้มีจำนวนคนกดไลค์ที่สูงขึ้น', NULL, 0);
INSERT OR IGNORE INTO choices (id, question_id, order_num, choice_text, choice_image, is_correct) VALUES ('ce4b33b9-3207-4b23-b8e2-596cc4a2c5c2', '6a25ff62-a05e-4971-93a6-27da06929903', 2, 'ฝ้ายจ้างคนที่มีคนติดตามในสื่อโซเชียลจำนวนมากถ่ายคลิปโฆษณาผลิตภัณฑ์ของตนเพื่อประชาสัมพันธ์', NULL, 0);
INSERT OR IGNORE INTO choices (id, question_id, order_num, choice_text, choice_image, is_correct) VALUES ('d378ee9f-3655-4dec-8e06-1c4bff0ce5ce', '6a25ff62-a05e-4971-93a6-27da06929903', 3, 'ฟ้าตัดต่อรูปภาพดาราที่ตนเองชื่นชอบลงในเฟซบุ๊กส่วนตัว แล้วเปิดเป็นสาธารณะให้คนเข้ามาดูได้', NULL, 0);
INSERT OR IGNORE INTO choices (id, question_id, order_num, choice_text, choice_image, is_correct) VALUES ('4bc9b1e9-5486-4dfb-9e8f-f676877c79de', '6a25ff62-a05e-4971-93a6-27da06929903', 4, 'ฝนเดินทางไปท่องเที่ยงตามสถานที่ต่างๆ และถ่ายภาพมาเพื่อใช้ประกอบในบล็อกนำเที่ยวของตนเอง', NULL, 1);
